import React, { useState, useEffect } from "react";
import MessageInput from "./components/MessageInput";
import ChatWindow from "./components/ChatWindow";
import LoadingIndicator from "./components/LoadingIndicator";
import "./App.css";

function App() {
  const [messages, setMessages] = useState([]);
  const [loading, setLoading] = useState(false);

  // Fetch chat history from the backend
  useEffect(() => {
    fetch("http://localhost:5000/messages")
      .then((res) => res.json())
      .then((data) => setMessages(data));
  }, []);

  // Handle message sending
  const handleSendMessage = async (userMessage) => {
    const newMessage = { text: userMessage, sender: "user" };
    setMessages((prevMessages) => [...prevMessages, newMessage]);

    // Post user message to the server
    await fetch("http://localhost:5000/messages", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(newMessage),
    });

    // Send message to AI and get response
    setLoading(true);
    const aiResponse = await fetchDeepAIResponse(userMessage);
    setLoading(false);

    const aiMessage = { text: aiResponse, sender: "ai" };
    setMessages((prevMessages) => [...prevMessages, aiMessage]);

    // Post AI message to server
    await fetch("https://api.openai.com/v1/chat/completions", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(aiMessage),
    });
  };

  // Fetch response from DeepAI
  const fetchDeepAIResponse = async (userMessage) => {
    try {
      const response = await fetch("https://api.openai.com/v1/chat/completions"
        , {
        method: "POST",
        headers: {
          "$OPENAI_API_KEY": "Authorization: Bearer YOUR_ACTUAL_API_KEY",  // Replace this with your actual API key
        },
        body: JSON.stringify({
          text: userMessage,
        }),
      });

      if (!response.ok) {
        throw new Error("Failed to fetch response from DeepAI");
      }

      const data = await response.json();
      return data.output;  // DeepAI returns the response under "output"
    } catch (error) {
      console.error("Error fetching from DeepAI:", error);
      return "Sorry, I couldn't generate a response right now.";
    }
  };

  return (
    <div className="App">
      <ChatWindow messages={messages} />
      {loading ? (
        <LoadingIndicator />
      ) : (
        <MessageInput onSendMessage={handleSendMessage} />
      )}
    </div>
  );
}

export default App;
